def _sha(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def _file(root: Path, name: str) -> Path:
    relative = PurePosixPath(name)
    path = root / name
    if (not name or relative.is_absolute() or '..' in relative.parts or '\\' in name
            or relative.as_posix() != name or path.is_symlink() or not path.is_file()
            or not path.resolve().is_relative_to(root.resolve())):
        raise ValueError('Unsafe or missing nine-line reading file: ' + str(name))
    return path


def _bytes(root: Path, name: str) -> bytes:
    _file(root, name)
    return representative_studies_predecessor_bytes(root, name)


def _json(root: Path, name: str):
    return json.loads(_bytes(root, name))


def _record_set(data: dict) -> tuple[list, list]:
    records, pool = data.get('reversible_text_files'), data.get('reverse_text_patch_pool')
    row_keys = {'path', 'old_sha256', 'old_bytes', 'new_sha256', 'new_bytes', 'edits'}
    if (not isinstance(records, list) or not isinstance(pool, list) or not pool
            or any(not isinstance(row, dict) or set(row) != row_keys for row in records)
            or len(records) != len(PREDECESSOR_FILES)
            or any(not isinstance(row['path'], str) for row in records)
            or {row['path'] for row in records} != set(PREDECESSOR_FILES)
            or len({row['path'] for row in records}) != len(records)):
        raise ValueError('Nine-line reading requires exactly the fixed predecessor file set')
    for pair in pool:
        if (not isinstance(pair, dict) or set(pair) != {'old', 'new'}
                or not all(isinstance(pair[k], str) for k in ('old', 'new'))
                or pair['old'] == pair['new']):
            raise ValueError('Invalid nine-line reading reverse replacement pool')
    used = set()
    for row in records:
        if (any(type(row[k]) is not int or row[k] < 0 for k in ('old_bytes', 'new_bytes'))
                or any(not isinstance(row[k], str) or not re.fullmatch(r'[0-9a-f]{64}', row[k])
                    for k in ('old_sha256', 'new_sha256'))
                or not isinstance(row['edits'], list) or not row['edits']):
            raise ValueError('Incomplete nine-line reading predecessor identity or edits')
        for edit in row['edits']:
            if (not isinstance(edit, dict) or set(edit) != {'old_offset', 'replacement'}
                    or type(edit['old_offset']) is not int or edit['old_offset'] < 0
                    or type(edit['replacement']) is not int
                    or not 0 <= edit['replacement'] < len(pool)):
                raise ValueError('Invalid nine-line reading exact reverse edit')
            used.add(edit['replacement'])
    if used != set(range(len(pool))):
        raise ValueError('Nine-line reading requires exactly its used replacement pool')
    return records, pool


def predecessor_bytes(root: Path, name: str) -> bytes:
    """Recover exact d5d8807 bytes without mutating files or weakening v33."""
    current = _bytes(root, name)
    if name not in CHANGED_FILES or not (root / MANIFEST).exists():
        return current
    if not FROZEN:
        raise ValueError('Nine-line reading publication is not frozen')
    data = _json(root, MANIFEST)
    if not isinstance(data, dict):
        raise ValueError('Nine-line reading manifest must be an object')
    records, pool = _record_set(data)
    row = next(row for row in records if row['path'] == name)
    old_sha, old_size = PREDECESSOR_FILES[name]
    if (row['old_sha256'] != old_sha or row['old_bytes'] != old_size
            or _sha(current) != row['new_sha256'] or len(current) != row['new_bytes']):
        raise ValueError('Nine-line reading file differs from old/new identities: ' + name)
    chunks, cursor, old_end, delta = [], 0, 0, 0
    for edit in row['edits']:
        offset, pair = edit['old_offset'], pool[edit['replacement']]
        before, after = pair['old'].encode('utf-8'), pair['new'].encode('utf-8')
        position = offset + delta
        if (offset < old_end or offset + len(before) > old_size
                or position < cursor or position + len(after) > len(current)
                or current[position:position + len(after)] != after):
            raise ValueError('Nine-line reading inverse differs at exact offset: ' + name)
        chunks.extend((current[cursor:position], before))
        cursor, old_end = position + len(after), offset + len(before)
        delta += len(after) - len(before)
    rebuilt = b''.join((*chunks, current[cursor:]))
    if _sha(rebuilt) != old_sha or len(rebuilt) != old_size:
        raise ValueError('Nine-line reading predecessor reconstruction failed: ' + name)
    return rebuilt


def _binding(root: Path, name: str) -> dict:
    value = _bytes(root, name)
    return {'path': name, 'sha256': _sha(value), 'bytes': len(value)}


def _marked(source: str, begin: str, end: str) -> str:
    if source.count(begin) != 1 or source.count(end) != 1:
        raise ValueError('Nine-line display requires unique markers: ' + begin)
    a, b = source.index(begin) + len(begin), source.index(end)
    if a > b:
        raise ValueError('Nine-line display marker order changed')
    return source[:a] + '<NINE-LINE-REGION/>' + source[b:]


def _mask_a07_details(source: str) -> str:
    articles = list(re.finditer(r'<article\b[^>]*\bid="line-a07"[^>]*>.*?</article>', source, re.S))
    if len(articles) != 1:
        raise ValueError('Nine-line reading requires the original A07 article')
    article = articles[0]
    details = list(re.finditer(
        r'<details><summary>(?:依据、边界与下一步|原文与研究范围)</summary>.*?</details>',
        article.group(), re.S))
    if len(details) != 1:
        raise ValueError('Nine-line reading requires one A07 source-details region')
    detail = details[0]
    if not article.group()[:detail.start()].rstrip().endswith('</p>'):
        raise ValueError('A07 source details must follow the original reading-entry paragraph')
    a, b = article.start() + detail.start(), article.start() + detail.end()
    return source[:a] + '<A07-SOURCE-DETAILS/>' + source[b:]


def _check_html_regions(route: str, before: bytes, after: bytes) -> None:
    source, current = before.decode('utf-8'), after.decode('utf-8')
    if route == 'index.html':
        a = _marked(source, '<!-- HERITAGE_SOURCES_BEGIN -->', '<!-- HERITAGE_SOURCES_END -->')
        b = _marked(current, '<!-- HERITAGE_SOURCES_BEGIN -->', '<!-- HERITAGE_SOURCES_END -->')
        a, b = _mask_a07_details(a), _mask_a07_details(b)
    elif route == 'achievements/index.html':
        a = _marked(source, '<!-- HERITAGE_INVENTORY_BEGIN -->', '<!-- HERITAGE_INVENTORY_END -->')
        b = _marked(current, '<!-- HERITAGE_INVENTORY_BEGIN -->', '<!-- HERITAGE_INVENTORY_END -->')
        old, new = '九线资料与缺口盘点', '九条成果线学术导读'
        if a.count(old) != 1 or b.count(new) != 1:
            raise ValueError('Nine-line reading top anchor label is ambiguous')
        a = _mask_a07_details(a.replace(old, new, 1))
        b = _mask_a07_details(b)
    else:
        raise ValueError('Unauthorized nine-line HTML route: ' + route)
    if a != b:
        raise ValueError('Nine-line reading changed bytes outside its bounded regions: ' + route)
    scripts = re.compile(r'<script\b[^>]*\btype\s*=\s*["\']application/(?:ld\+)?json["\'][^>]*>.*?</script\s*>', re.I | re.S)
    if scripts.findall(source) != scripts.findall(current):
        raise ValueError('Nine-line reading changed original embedded JSON: ' + route)
    old_ids, new_ids = re.findall(r'\bid="([^\"]+)"', source), re.findall(r'\bid="([^\"]+)"', current)
    if not set(old_ids).issubset(new_ids) or len(new_ids) != len(set(new_ids)):
        raise ValueError('Nine-line reading lost or duplicated original IDs: ' + route)


def apply(root: Path, entries: dict, previous_report: dict) -> tuple[dict, dict]:
    """Validate the reviewed v34 delta after the exact v1-v33 replay."""
    if (root / REPRESENTATIVE_STUDIES_MANIFEST).exists() and not (root / MANIFEST).exists():
        raise ValueError('Representative studies require their immutable v34 predecessor')
    if not (root / MANIFEST).exists():
        return entries, previous_report
    if not FROZEN:
        raise ValueError('Nine-line reading must be frozen after source/display review')
    if not (root / PREVIOUS_MANIFEST).is_file():
        raise ValueError('Nine-line reading requires its immutable v33 predecessor')
    for name, sha in OLD_MANIFESTS.items():
        if _sha(_bytes(root, name)) != sha:
            raise ValueError('Historical presentation manifest changed: ' + name)
    for name, (sha, size) in PROTECTED_FILES.items():
        value = _bytes(root, name)
        if _sha(value) != sha or len(value) != size:
            raise ValueError('Nine-line reading changed protected source bytes: ' + name)
    site_paths = tuple(sorted(p.relative_to(root / 'site').as_posix()
        for p in (root / 'site').rglob('*') if p.is_file()))
    if site_paths != EXPECTED_SITE_PATHS:
        raise ValueError('Nine-line reading added or removed an unlisted website member')
    data = _json(root, MANIFEST)
    required = {
        'schema_version': '34.0', 'presentation_id': PRESENTATION_ID,
        'publication_kind': 'platform_nine_line_academic_reading',
        'previous_presentation_commit': PREVIOUS_COMMIT,
        'previous_presentation': {'path': PREVIOUS_MANIFEST, 'sha256': OLD_MANIFESTS[PREVIOUS_MANIFEST]},
        'original_baseline_sha256': BASELINE_SHA256, 'original_archive_sha256': ARCHIVE_SHA256,
        'allowed_html_paths': list(ROUTES), 'added_html_paths': [], 'additions': [],
        'allowed_display_regions': {
            'index.html': ['HERITAGE_SOURCES visible reference text', 'article#line-a07 source details'],
            'achievements/index.html': ['HERITAGE_INVENTORY academic reading guide',
                'exact top inventory anchor label', 'article#line-a07 source details'],
        },
        'editorial_documents': [_binding(root, name) for name in DOCUMENTS],
        'protected_website_members': {name: {'sha256': row['sha256'], 'bytes': row['bytes']}
            for name, row in entries.items() if name not in ROUTES},
        'reconstruction_kind': 'deduplicated_exact_utf8_text_edits',
        'scientific_review_status': 'review_required', 'release_eligible': False,
        'scientific_data_unchanged': True, 'M0_resumed': False,
        'historical_achievement_independent_of_AI_review': True,
        'allowed_ai_json_pointers': [], 'allowed_new_files': list(NEW_FILES),
    }
    if (not isinstance(data, dict) or any(data.get(k) != v for k, v in required.items())
            or any(data.get(k) is not required[k] for k in ('release_eligible',
                'scientific_data_unchanged', 'M0_resumed', 'historical_achievement_independent_of_AI_review'))
            or any(type(data.get(k)) is not int or data[k] != 0 for k in
                ('new_quantum_calls', 'new_model_API_calls', 'new_model_training_runs'))
            or not isinstance(data.get('authorization'), str) or not data['authorization'].strip()):
        raise ValueError('Unsupported bounded nine-line academic reading presentation v34')
    _record_set(data)
    for name, identity in PREDECESSOR_FILES.items():
        old = predecessor_bytes(root, name)
        if (_sha(old), len(old)) != identity or old == _bytes(root, name):
            raise ValueError('Nine-line predecessor differs from fixed d5d8807: ' + name)
    for name, sha in REVIEWED_PUBLIC_FILES.items():
        if _sha(_bytes(root, name)) != sha:
            raise ValueError('Nine-line source, renderer or document differs from reviewed bytes: ' + name)
    for name in (*('site/' + route for route in ROUTES), CONTENT, DOCUMENT):
        value = _file(root, name).read_text('utf-8')
        if re.search(r'(?i)private-sources|current-item-register|现阶段待查事项统计|[CD]:[\\/]', value):
            raise ValueError('Nine-line public display contains private evidence or a local path: ' + name)
    changes = data.get('changes')
    if (not isinstance(changes, list) or len(changes) != len(ROUTES)
            or any(not isinstance(row, dict) for row in changes)
            or {row.get('path') for row in changes} != set(ROUTES)):
        raise ValueError('Nine-line reading may change only two existing routes')
    updated = {name: dict(row) for name, row in entries.items()}
    for item in changes:
        route = item['path']
        before, after = predecessor_bytes(root, 'site/' + route), _bytes(root, 'site/' + route)
        old = entries[route]
        if (item.get('old_sha256') != old['sha256'] or item.get('old_bytes') != old['bytes']
                or _sha(before) != old['sha256'] or len(before) != old['bytes']
                or item.get('new_sha256') != _sha(after) or item.get('new_bytes') != len(after)
                or before == after or not isinstance(item.get('reason'), str) or not item['reason'].strip()):
            raise ValueError('Nine-line route differs from old/new byte identities: ' + route)
        _check_html_regions(route, before, after)
        updated[route] = {**old, 'sha256': _sha(after), 'bytes': len(after), 'presentation_id': PRESENTATION_ID}
    for name, item in updated.items():
        value = _bytes(root, 'site/' + name)
        if _sha(value) != item['sha256'] or len(value) != item['bytes']:
            raise ValueError('Nine-line reading changed an unlisted website byte: ' + name)
    from render_nine_line_reading import inspect_reading, render_document
    check = inspect_reading(root)
    if check.get('status') != 'passed' or _file(root, DOCUMENT).read_bytes() != render_document(root).encode('utf-8'):
        raise ValueError('Nine-line reading differs from its source rendering: ' + str(check))
    report = {'path': MANIFEST, 'sha256': _sha(_bytes(root, MANIFEST)),
        'presentation_id': PRESENTATION_ID, 'publication_kind': required['publication_kind'],
        'changed_paths': list(ROUTES), 'added_paths': [],
        'previous_presentation_commit': PREVIOUS_COMMIT,
        'exact_predecessor_reconstruction': True, 'source_derived_rendering': True,
        'all_v1_v33_manifest_bytes_preserved': True, 'private_originals_not_published': True,
        'original_data_and_embedded_JSON_preserved': True,
        'eight_AI_research_lines_and_scientific_data_preserved': True,
        **{k: required[k] for k in ('scientific_review_status', 'release_eligible',
            'scientific_data_unchanged', 'M0_resumed', 'historical_achievement_independent_of_AI_review')}}
    return apply_representative_studies(root, updated, {**report, 'presentation_chain': [*previous_report['presentation_chain'], report]})
